</style>
<script>
document.addEventListener('DOMContentLoaded', function () {
    const periodMode = document.querySelector('[data-period-mode]');
    const syncPeriodFields = function () {
        const custom = periodMode?.value === 'custom';
        const quarter = periodMode?.value === 'quarter';
        document.querySelectorAll('[data-custom-field]').forEach(function (field) { field.hidden = !custom; });
        document.querySelectorAll('[data-quarter-field]').forEach(function (field) { field.hidden = !quarter; });
    };
    periodMode?.addEventListener('change', syncPeriodFields);
    syncPeriodFields();
    let activeModal = null;
    let trigger = null;
    const closeModal = function () {
        if (!activeModal) return;
        activeModal.hidden = true;
        activeModal.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
        trigger?.focus();
        activeModal = null;
    };
    document.querySelectorAll('[data-bot-modal]').forEach(function (button) {
        button.addEventListener('click', function () {
            trigger = button;
            activeModal = document.getElementById('bot-modal-' + button.dataset.botModal);
            if (!activeModal) return;
            activeModal.hidden = false;
            activeModal.setAttribute('aria-hidden', 'false');
            document.body.style.overflow = 'hidden';
            activeModal.querySelector('[data-bot-modal-close]')?.focus();
        });
    });
    document.querySelectorAll('[data-bot-modal-close]').forEach(function (button) { button.addEventListener('click', closeModal); });
    document.querySelectorAll('.bot-modal').forEach(function (modal) { modal.addEventListener('click', function (event) { if (event.target === modal) closeModal(); }); });
    document.addEventListener('keydown', function (event) { if (event.key === 'Escape') closeModal(); });
});
</script>
@endsection
